import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../services/supabaseService';
import LiveRoom from '../../components/academy/LiveRoom';
import { useToast } from '../../contexts/ToastContext';
import Icon from '../../components/AppIcon';

const LiveSessionPage = () => {
    const { meetingId } = useParams();
    const navigate = useNavigate();
    const { addToast } = useToast();
    const { user } = useSelector(state => state.auth);
    
    const [session, setSession] = useState(null);
    const [token, setToken] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [profile, setProfile] = useState(null);

    // Fetch latest profile data to ensure we have the full name
    useEffect(() => {
        const fetchLatestProfile = async () => {
            if (user?.id) {
                try {
                    const data = await supabaseService.getProfile(user.id);
                    setProfile(data);
                } catch (err) {
                    console.error("Error fetching profile:", err);
                }
            }
        };
        fetchLatestProfile();
    }, [user?.id]);

    useEffect(() => {
        const joinSession = async () => {
            try {
                // 1. Fetch session details
                const sessionData = await supabaseService.getLiveSessionByMeetingId(meetingId);
                
                if (!sessionData || sessionData.status === 'ended') {
                    setError("This session has ended or doesn't exist.");
                    setLoading(false);
                    return;
                }
                
                setSession(sessionData);

                // 2. Get secure token
                // Priority: 1. Live Profile, 2. Auth Metadata, 3. Auth Store, 4. Email
                const fullName = profile?.full_name || user?.user_metadata?.full_name || user?.full_name;
                const emailName = user?.email?.split('@')[0]?.replace(/[0-9]/g, '');
                const identity = fullName?.trim() || emailName || 'Member';
                
                const liveToken = await supabaseService.getLiveSessionToken(sessionData.meeting_id, identity);
                setToken(liveToken);
                
            } catch (err) {
                console.error("Failed to join session:", err);
                setError("Failed to connect to the session. Please try again.");
            } finally {
                setLoading(false);
            }
        };

        if (meetingId) {
            joinSession();
        }
    }, [meetingId, user, addToast]);

    if (loading) {
        return (
            <div className="min-h-screen bg-[#0A0C10] flex flex-col items-center justify-center">
                <div className="w-16 h-16 border-4 border-brand-blue border-t-transparent rounded-full animate-spin mb-6" />
                <p className="text-slate-400 font-bold tracking-widest animate-pulse">CONNECTING TO ROOM...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-[#0A0C10] flex flex-col items-center justify-center p-4 text-center">
                <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mb-6">
                    <Icon name="AlertCircle" className="text-red-500" size={40} />
                </div>
                <h1 className="text-2xl font-black italic mb-2 uppercase">Room Unavailable</h1>
                <p className="text-slate-400 mb-8 max-w-md">{error}</p>
                <button 
                    onClick={() => navigate('/academy/brainstorm')}
                    className="bg-brand-blue text-white font-black italic px-8 py-3 rounded-xl hover:scale-105 transition-transform"
                >
                    BACK TO HUB
                </button>
            </div>
        );
    }

    return (
        <div className="h-screen bg-[#0A0C10] overflow-hidden">
            {session && token && (
                <LiveRoom 
                    token={token}
                    roomName={session.meeting_id}
                    isHost={user?.id === session.host_id}
                    adminIdentity={user?.id}
                    sessionId={session.id}
                    onDisconnect={() => navigate('/academy/brainstorm')}
                />
            )}
        </div>
    );
};

export default LiveSessionPage;
